// Carts with this many lines or more get the bulk discount.
const BULK_MIN_LINES = 10;
const BULK_DISCOUNT_RATE = 0.05;

// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount, applied once
// after the customer discount. The result is rounded once, at the end.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= BULK_MIN_LINES ? BULK_DISCOUNT_RATE : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
