import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// n lines of `price` each, qty 1.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// Issue #12: totals for discount rate 0 must stay as they are.
test('discount 0: 9 lines get no bulk discount', () => {
  assert.equal(total(lines(9, 1000), 0), 9000);
});

test('discount 0: 10 lines get the 5% bulk discount once', () => {
  assert.equal(total(lines(10, 1000), 0), 9500);
});

test('discount 0: total is rounded once, half up (313.5 -> 314)', () => {
  assert.equal(total(lines(10, 33), 0), 314);
});

// Issue #12: the customer discount is applied exactly once.
test('discount 0.1 on a 1,000 cart under 10 lines totals 900', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

// 10,000 -> customer discount 10% -> 9,000 -> bulk discount 5% -> 8,550
test('discount 0.1 on 10 lines: customer discount, then the bulk discount once', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
